/**
 * Self-initializing database — the Gitea/Grafana pattern.
 *
 * A fresh NexNotes install (npm run dev, Docker first boot, desktop shell,
 * Vercel + Neon) used to answer every request with
 * "schema is out of date — run `npx prisma db push`". Now the server itself
 * creates its tables the first time anything touches an empty database:
 *
 *   1. a cheap probe (`SELECT 1 FROM "User"`) classifies the failure;
 *   2. on a missing schema it executes the committed DDL snapshot
 *      (prisma/db-init.<driver>.sql, regenerated by `npm run db:ddl`);
 *   3. the DDL is made idempotent at runtime (CREATE … IF NOT EXISTS, and
 *      Postgres constraint adds wrapped in duplicate_object-swallowing DO
 *      blocks by the generator), so boot-time, restart-time and racing
 *      serverless cold starts can all run it safely;
 *   4. a re-probe proves the schema is live before requests are retried.
 *
 * Escape hatch: NEXNOTES_AUTO_MIGRATE=0 restores the old behaviour —
 * controlled migrations only (what most enterprises run through a release
 * pipeline: `prisma migrate deploy` from CI/CD). No snapshot file → no
 * auto-DDL either; the honest 503 from db-errors.ts still tells the operator
 * exactly what to do.
 */
import fs from "node:fs";
import path from "node:path";
import { db } from "@/lib/db";
import { currentDriver } from "@/lib/db-errors";

/** The slice of PrismaClient this module actually touches — tests can pass a
 *  bare client pointed at a scratch database. */
export interface RawSqlClient {
  $queryRawUnsafe(sql: string): Promise<unknown>;
  $executeRawUnsafe(sql: string): Promise<unknown>;
  $transaction(statements: Promise<unknown>[]): Promise<unknown>;
}

const SCHEMA_MISSING_CODES = new Set(["P2021", "P2022", "P1003"]);

/** True when the error means "the database is fine but has no (or an old)
 *  schema" — the one situation boot-DDL can fix. */
export function isSchemaMissingError(e: unknown): boolean {
  const err = e as { code?: unknown; message?: unknown };
  const code = typeof err?.code === "string" ? err.code : "";
  if (SCHEMA_MISSING_CODES.has(code)) return true;
  const message = typeof err?.message === "string" ? err.message : "";
  // Engine-level fallbacks that carry no P-code:
  //   SQLite:  "no such table: User" / "no such column: …"
  //   Postgres: `relation "User" does not exist` / column … does not exist
  return /no such table|no such column|relation .* does not exist|column .* does not exist/i.test(message);
}

/** Turn a `migrate diff` script into re-runnable DDL: CREATE statements gain
 *  IF NOT EXISTS. (Postgres ALTER … ADD CONSTRAINT is already DO-block-wrapped
 *  by scripts/gen-ddl.mjs.) */
export function makeIdempotent(sql: string): string {
  return sql
    .replace(/CREATE TABLE (?!IF NOT EXISTS)/g, "CREATE TABLE IF NOT EXISTS ")
    .replace(/CREATE UNIQUE INDEX (?!IF NOT EXISTS)/g, "CREATE UNIQUE INDEX IF NOT EXISTS ")
    .replace(/CREATE INDEX (?!IF NOT EXISTS)/g, "CREATE INDEX IF NOT EXISTS ");
}

/** Split a SQL script into executable statements, honouring '…' and "…"
 *  quoting and $$ dollar-quoting (the Postgres DO blocks), dropping
 *  comment-only fragments between statements. */
export function splitSqlStatements(sql: string): string[] {
  const out: string[] = [];
  let cur = "";
  let i = 0;
  let inSingle = false;
  let inDouble = false;
  let inDollar = false;
  while (i < sql.length) {
    const c = sql[i]!;
    const next = sql[i + 1];
    if (inDollar) {
      if (c === "$" && next === "$") {
        inDollar = false;
        cur += "$$";
        i += 2;
      } else {
        cur += c;
        i += 1;
      }
      continue;
    }
    if (c === "'" && !inDouble) {
      inSingle = !inSingle;
      cur += c;
      i += 1;
      continue;
    }
    if (c === '"' && !inSingle) {
      inDouble = !inDouble;
      cur += c;
      i += 1;
      continue;
    }
    if (c === "$" && next === "$" && !inSingle && !inDouble) {
      inDollar = true;
      cur += "$$";
      i += 2;
      continue;
    }
    if (c === "-" && next === "-") {
      const end = sql.indexOf("\n", i);
      const stop = end === -1 ? sql.length : end;
      cur += sql.slice(i, stop);
      i = stop;
      continue;
    }
    if (c === ";" && !inSingle && !inDouble) {
      out.push(cur.trim());
      cur = "";
      i += 1;
      continue;
    }
    cur += c;
    i += 1;
  }
  if (cur.trim()) out.push(cur.trim());
  return out
    .map((s) => {
      // strip leading comment-only lines — they carry no SQL
      const body = s.replace(/^(--[^\n]*\n?)+/, "").trim();
      return body.length > 0 ? body : null;
    })
    .filter((s): s is string => s !== null);
}

/** Where the committed snapshot lives, in lookup order: repo layout
 *  (<cwd>/prisma/), standalone-server layout (finish-build.mjs copies the
 *  files next to server.js), and the standalone parent layout. */
export function resolveDdlPath(driver: "postgres" | "sqlite"): string[] {
  const name = `db-init.${driver}.sql`;
  return [
    path.join(process.cwd(), "prisma", name),
    path.join(process.cwd(), name),
    path.join(process.cwd(), "..", "prisma", name),
  ];
}

function loadDdl(driver: "postgres" | "sqlite"): string | null {
  for (const p of resolveDdlPath(driver)) {
    try {
      if (fs.existsSync(p)) return fs.readFileSync(p, "utf8");
    } catch {
      // unreadable file → try the next candidate
    }
  }
  return null;
}

/** True when the tables are already there. */
async function probe(client: RawSqlClient): Promise<boolean> {
  try {
    await client.$queryRawUnsafe('SELECT 1 FROM "User" LIMIT 1');
    return true;
  } catch (e) {
    if (isSchemaMissingError(e)) return false;
    throw e; // unreachable DB, read-only FS, … → not our job to fix
  }
}

/** Probe → apply snapshot → re-probe. Returns true when it created anything. */
export async function runSchemaBootstrap(client: RawSqlClient): Promise<boolean> {
  if (await probe(client)) return false;
  const driver = currentDriver();
  const raw = loadDdl(driver);
  if (!raw) return false; // snapshot not shipped → honest 503 path stays
  const statements = splitSqlStatements(makeIdempotent(raw));
  await client.$transaction(statements.map((s) => client.$executeRawUnsafe(s)));
  if (!(await probe(client))) {
    throw new Error("db-bootstrap ran its DDL but the schema probe still fails");
  }
  console.log(`[db-bootstrap] ${driver} schema ready — ${statements.length} statements applied`);
  return true;
}

let bootPromise: Promise<boolean> | null = null;

/** Once per process: make sure the schema exists before a request retries.
 *  Never throws for "already fine"; throws onward when the DB is truly
 *  unreachable so callers keep their existing error handling. */
export async function ensureSchemaReady(client: RawSqlClient = db as unknown as RawSqlClient): Promise<boolean> {
  if (process.env.NEXNOTES_AUTO_MIGRATE === "0") return false;
  if (client !== (db as unknown as RawSqlClient)) return runSchemaBootstrap(client);
  if (!bootPromise) {
    bootPromise = runSchemaBootstrap(db as unknown as RawSqlClient).catch((e) => {
      bootPromise = null; // allow a later request to retry after the operator fixed something
      throw e;
    });
  }
  return bootPromise;
}

/** Route-side helper: on a schema-missing failure, bootstrap once and run the
 *  handler again; anything else (or a second failure) hands the original
 *  error back to the caller's normal handling. */
export async function retryAfterSchemaBootstrap(
  e: unknown,
  handler: () => Promise<Response>,
): Promise<Response | null> {
  if (!isSchemaMissingError(e)) return null;
  try {
    await ensureSchemaReady();
    return await handler();
  } catch {
    return null; // still broken → caller's catch renders the honest 503
  }
}
